settings.custom_css:
:where(h1,h2,h3).m\:text-black {
  color: var(--color-heading-text);
}
.m-hero__subtitle,
.m-section__subheading,
.m-hero__subtitle,
.sf__index-hero .m-hero__text {
  font-weight: 600;
  font-family: 'M-Body-Font';
  text-transform: uppercase;
  letter-spacing: 1px;
}
.m-hero__text {
  font-family: 'M-Body-Font';
}
.sf__index-hero .m-hero__content .m-hero__subtitle {
  margin-bottom: 60px;
}
.sf__index-hero .m-hero__title {
  margin-bottom: 18px;
}
.sf__index-hero .m-hero__text {
  margin-bottom: 45px;
  color: var(--color-body-text);
}

.sf__index-custom-html .section__heading {
  margin-bottom: 13px;
}
.sf__index-custom-html .block__content-header {
  margin-bottom: 40px;
}
.sf__index-custom-html .block__content-body {
  margin-bottom: 60px;
}
.sf__index-custom-html .block__content-body h3 {
  font-size: 24px;
  line-height: 1.33;
  margin-bottom: 10px;
}
.sf__index-custom-html .block__content-header p,
.sf__index-custom-html .block__content-body p {
  font-size: 15px;
}
.sf__index-custom-html .block__content-footer {
  padding-top: 24px;
  margin-top: 90px;
  border-top: 1px solid #ededed;
}
.sf__index-custom-html .block__content-footer .block__item h4 {
  font-size: 48px;
  line-height: 1.33;
}
.sf__index-custom-html .block__content-footer .block__item p {
  font-size: 18px;
}
.sf__index-hero-1 {
  background-color: #FAF8F4;
}
.sf__index-hero-1 .m-hero--content-stack {
  margin-bottom: 0 !important;
}
.sf__index-hero-1 .m-hero__content .m-hero__subtitle {
  margin-bottom: 30px;
}
.sf__index-hero-1 .m-hero__content .m-hero__title {
  margin-bottom: 10px;
}
.sf__index-hero-1 .m-hero__content .m-hero__text {
  margin-bottom: 50px;
}
.sf__index-icon-box .m-section-py {
  padding-top: 50px;
}
.sf__index-icon-box .m-icon-box__content {
  margin-top: 28px;
}
.sf__index-icon-box .m-icon-box__content h3 {
  line-height: 1.33;
  font-size: 24px;
  margin-bottom: 8px;
}
.sf__index-icon-box .m-icon-box__content .m-icon-box__description {
  font-size: 15px;
}
.sf__index-press {
  background-image: url("https://cdn.shopify.com/s/files/1/0595/7291/2305/files/bg-2_756d0ce8-7c87-4a6f-9044-0d2eafdcd3b8.jpg?v=1632109894");
  background-position: top;
  background-size: cover;
  background-repeat: no-repeat;
}
.sf__index-press .m-press__content {
  background-image: url("https://cdn.shopify.com/s/files/1/0595/7291/2305/files/bg-3.svg?v=1632110218");
  background-repeat: no-repeat;
  background-position: 50% 10%;
  padding-top: 100px;
  padding-bottom: 50px;
}
.sf__index-press .m-press__inner {
  padding-top: 100px;
}
.sf__index-press .m-press__content .m-press__title {
  line-height: 1.4;
  font-size: 34px;
  font-family: "M-Heading-Font";
  max-width: 100%;
}
.sf__index-press .m-press__logo .m-image {
  max-width: var(--max-width, 100%);
}

.sf__index-hero-2 .m-hero__bg {
  top: 70px;
  left: 50px;
  right: 50px;
  width: calc(100% - 100px);
}
.sf__index-hero-2 .m-hero__subtitle {
  background-image: url("https://cdn.shopify.com/s/files/1/0595/7291/2305/files/icon-4.svg?v=1632112223");
  padding: 150px 0 50px;
  background-repeat: no-repeat;
  background-position: center;
  margin-bottom: 0;
}

@media (min-width: 1536px) {
}

@media (min-width: 768px) {
  .m-icon-box--home .m-icon-box .m-section-py {
    padding-top: 0;
  }
}

@media (max-width: 767px) {
  .sf__index-hero .m-hero__content {
    text-align: center;
  }
  .sf__index-hero .m-hero__content .m-hero__subtitle {
    margin-bottom: 20px;
  }
  .sf__index-hero .m-hero__content .m-hero__subtitle img {
    max-width: 80px;
    margin: 0 auto;
  }
  .sf__index-hero .m-hero__inner {
    padding-top: 0;
    padding-bottom: 40px;
  }
  .sf__index-hero .m-hero__title {
    font-size: 36px;
  }
  .sf__index-hero .m-hero__text {
    margin-bottom: 30px;
  }

  .sf__index-custom-html .block__content-body {
    margin-bottom: 30px;
  }
  .sf__index-custom-html .block__content-footer {
    margin-top: 30px;
  }
  .sf__index-custom-html .block__content-footer .block__item h4 {
    font-size: 32px;
  }
  .sf__index-hero-1 .m-hero__content .m-hero__title {
    font-size: 36px;
  }
  .sf__index-hero-1 .m-hero__inner {
    padding-top: 40px;
    padding-bottom: 0;
  }
  .sf__index-hero-1 .m-hero__content .m-hero__text {
    margin-bottom: 30px;
    color: var(--color-sub-text);
  }
  .sf__index-press {
    margin-top: -100px;
    z-index: 0;
  }
  .sf__index-press .m-press__content {
    background-size: 40%;
    padding-top: 0;
    padding-bottom: 0;
  }
  .sf__index-hero-2 .m-hero__inner {
    padding-top: 40px;
    padding-bottom: 40px;
  }
  .sf__index-hero-2 .m-hero__subtitle {
    background-size: 30%;
    padding: 50px 0 10px;
  }
  .sf__index-hero-2 .m-hero__bg {
    top: 0;
    left: 0;
    right: auto;
    width: 100%;
  }
}
